var r=[{title:`Hur lång återhämtningen tar`,text:`Det beror på övningen, den totala volymen, intensiteten, sömnen, konditionen och hur bekant arbetet är. Efter ett hårt pass för en stor muskelgrupp är ungefär 48–72 timmar innan nästa lika hårda pass en vanlig planeringsriktlinje. Det är en riktlinje, och vissa behöver mer eller mindre.`},{title:`Tecken på att du inte har återhämtat dig`,text:`Träningsvärk som dröjer längre än vanligt, färre repetitioner med samma vikt, tunga ben, låg motivation och förändringar i tekniken kan alla tyda på för mycket trötthet. Ett dåligt pass bevisar inte överträning. Leta efter trender över flera pass, särskilt tillsammans med dålig sömn, sjukdom eller extra stress i resten av livet.`},{title:`Sprid ut det hårda arbetet`,text:`En typisk vecka kan ha helkroppsstyrka på måndag och torsdag, med lugna promenader andra dagar. Att träna styrka oftare kan fungera när du sprider övningar eller muskelgrupper över veckan och håller volymen i schack. Lätt konditionsträning eller rörlighet en dag utan lyft passar oftast bra med återhämtning.`},{title:`Hjälp kroppen att anpassa sig`,text:`Sträva efter regelbunden sömn, tillräckligt med mat och vatten, små träningsökningar och vilodagar när du behöver dem. Träningsvärk är inget betyg på hur bra passet var. Om din prestation fortsätter sjunka, minska volymen, välj lättare varianter eller lägg till återhämtningstid. Höj inte intensiteten för att kompensera.`},{title:`Så använder du TrainUp`,text:`Efter varje pass, skatta din ansträngning och rapportera eventuell smärta eller obehag. När du skapar programmet på nytt tittar TrainUp på minst 3 pass. Nylig smärta betyder ingen ökning. Om 2 av dina senaste 3 pass var mycket tuffa (RPE 9 eller mer) eller mindre än 60 % genomförda blir nästa program lättare. Historik visar din genomsnittliga ansträngning och ett diagram över 4 veckor. Om svåra symtom kvarstår, sök medicinsk rådgivning.`}];var n=[{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM 2026: träningsdos, återhämtning och progression`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC12965823/`},{label:`NHS: träningsvärk med fördröjd debut`,url:`https://www.leicspart.nhs.uk/msk-physiotherapy-resources-getting-started/msk-physiotherapy-resources-faqs/`}];var a={sections:r,sources:n};export{a as default,r as sections,n as sources};